import {initCheckout} from './checkout-selection.js';
import {templateCatalog} from './template-catalog.js';
import {getPlan,profilePlans,makeRevision,policyVersion} from './policy-v4.js';
const money=n=>'Rp'+n.toLocaleString('id-ID');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s+'T12:00:00Z').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Makassar'});
const policyLinks='<nav class="policy-links" aria-label="Kebijakan sebelum konfirmasi"><a href="terms.html">Syarat layanan</a><a href="cancellation-policy.html">Pembatalan & refund</a><a href="domain-policy.html">Domain</a><a href="renewal-policy.html">Renewal</a><a href="ownership-policy.html">Kepemilikan & data</a></nav>';
const templates=templateCatalog.map(t=>t.id);
const labels=templateCatalog.map(t=>t.name);
const options=(months)=>profilePlans.map(p=>`<option value="${p.months}" ${p.months===months?'selected':''}>${p.months} bulan${p.badge?' · '+p.badge:''}</option>`).join('');
function facts(items){return '<dl class="facts">'+items.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')+'</dl>';}
function feedback(node,message,error=false){node.textContent=message;node.className=error?'error':'result';node.setAttribute('role',error?'alert':'status');}
function errorFor(form,message,field){const output=form.querySelector('.error');feedback(output,message,true);if(field){field.setAttribute('aria-invalid','true');field.setAttribute('aria-describedby',output.id);field.focus();}}
function bindValidation(form){form.addEventListener('input',()=>{form.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));form.querySelector('.error').textContent='';});}
initCheckout();
const account=document.getElementById('account-app');
if(account){
  const key='rasio-policy-v4-demo';let state;
  const initial=()=>({start:'2026-10-15',end:'2030-10-15',domainEnd:'2027-10-15',domainRegistered:false,stopAtEnd:false,requests:[],materials:null});
  try{state=JSON.parse(sessionStorage.getItem(key));if(!state||!Array.isArray(state.requests)||!state.start||!state.end||!state.domainEnd)state=initial();}catch{state=initial();}
  function persist(){try{sessionStorage.setItem(key,JSON.stringify(state));return true;}catch{return false;}}
  const request=(kind,detail,extra={})=>{const r={id:'SIM-'+String(state.requests.length+1).padStart(4,'0'),kind,detail,...extra};state.requests.unshift(r);const saved=persist();return {...r,saved};};
  const requestLabels={subscription:'Langganan',domain:'Domain',data:'Data',revision:'Revisi',refund:'Refund',minor:'Revisi minor',major:'Perubahan besar',incident:'Gangguan',submitted:'Diajukan',triaged:'Sudah ditinjau',awaiting_material:'Menunggu materi',queued:'Dalam antrean',in_progress:'Dikerjakan',completed:'Selesai',needs_quote:'Menunggu penawaran',stop_at_end_of_term:'Berhenti pada akhir periode (simulasi)',renewal_requested:'Penawaran renewal diminta (simulasi)',refund_under_review:'Permohonan refund ditinjau (simulasi)',domain_transfer_requested:'Transfer diminta (simulasi)',domain_renewal_due:'Rincian renewal domain diminta (simulasi)',data_export_requested:'Ekspor diminta (simulasi)',data_deletion_requested:'Penghapusan diminta (simulasi)'};
  const viewLabels={subscription:'Langganan & tagihan',domain:'Domain',support:'Revisi website',data:'Data & kepemilikan',onboarding:'Materi website'};
  const list=(kind)=>{const items=state.requests.filter(r=>!kind||r.kind===kind);return items.length?'<ul class="request-list">'+items.map(r=>`<li><strong>${esc(r.id)} · ${esc(requestLabels[r.kind]||r.kind)}</strong><p>${esc(r.detail)}</p>${r.revision_type?`<small>${esc(requestLabels[r.revision_type])} · ${esc(requestLabels[r.revision_status])} · ${esc(r.scope)}</small>`:''}<p class="state-line">${esc(requestLabels[r.state]||'Permintaan simulasi tercatat; belum dikirim ke Rasio.')}</p></li>`).join('')+'</ul>':'<p class="empty">Belum ada permintaan simulasi.</p>';};
  function render(){const view=(location.hash==='#main'?'':location.hash.slice(1))||'subscription';document.querySelectorAll('.flow-links a').forEach(a=>a.setAttribute('aria-current',a.hash==='#'+view?'page':'false'));if(!viewLabels[view]){account.innerHTML='<section class="flow-card"><h2>Halaman tidak ditemukan</h2><a href="#subscription">Kembali ke langganan</a></section>';return;}document.title=viewLabels[view]+' — Rasio Labs';const reset='<div class="actions section-gap"><button id="reset-simulation" type="button">Reset data simulasi</button><a href="policy-review.html">Keputusan yang belum disetujui</a></div>';
    if(view==='subscription')account.innerHTML=`<div class="flow-grid"><section class="flow-card"><h2>RasioLabs Profile · 48 bulan</h2>${facts([['Mulai',date(state.start)],['Berakhir',date(state.end)],['Total periode contoh','Rp1.332.000'],['Penagihan otomatis','Tidak aktif (draf)'],['Status',state.stopAtEnd?'Berhenti pada akhir periode':'Aktif — data contoh']])}<p>Website dan CMS tetap aktif sampai akhir periode yang telah dibayar saat memilih Tidak Perpanjang. Refund dini ditinjau terpisah.</p><form id="stop-form" novalidate><label class="consent"><input id="stop-consent" type="checkbox"><span>Saya memahami layanan contoh tetap aktif sampai ${date(state.end)}.</span></label><p id="stop-error" class="error"></p><button ${state.stopAtEnd?'disabled':''}>Tidak Perpanjang</button><p id="stop-result" aria-live="polite"></p></form><details><summary>Usulan pengingat dan masa tenggang</summary><p>H-30, H-14, H-7, H-1; masa tenggang 14 hari. Belum disetujui bisnis/hukum atau diuji operasional. Tidak ada email/suspensi otomatis di prototipe.</p></details>${policyLinks}</section><section class="flow-card"><h2>Ajukan penawaran renewal</h2><label for="renew-duration">Durasi baru</label><select id="renew-duration">${options(12)}</select><div id="renew-summary"></div><button id="renew-request" class="primary">Minta penawaran renewal</button><p id="renew-result" aria-live="polite"></p><h2>Pembatalan dini / refund</h2><form id="refund-form" novalidate><label for="refund-stage">Tahap pengerjaan</label><select id="refund-stage"><option>Belum mulai setup</option><option>Setup sudah dimulai</option><option>Website sudah tayang</option><option>Layanan tidak sesuai kontrak</option></select><label for="refund-reason">Alasan permohonan</label><textarea id="refund-reason" maxlength="2000"></textarea><p id="refund-error" class="error"></p><button>Ajukan peninjauan refund</button><p id="refund-result" aria-live="polite"></p></form><p class="simulation">Usulan 7 hari sebelum setup/pengeluaran bukan jaminan refund otomatis. Formula, biaya pihak ketiga dan waktu proses masih perlu persetujuan.</p></section></div><section class="flow-card section-gap"><h2>Riwayat permintaan</h2>${list()}</section>${reset}`;
    if(view==='domain')account.innerHTML=`<section class="flow-card"><h2>Domain dikelola terpisah dari website</h2>${facts([['Domain','bisnis-contoh.test'],['Registran','Bisnis Contoh — data simulasi'],['Registrar','Belum dipilih'],['Berakhir (contoh terpisah)',date(state.domainEnd)],['Tahun pertama','Layak berdasarkan durasi 48 bulan'],['Status pendaftaran','Belum didaftarkan'],['Tarif renewal','Belum tersedia; bukan Rp0'],['Pembayaran domain','Belum dibayar']])}<p>Tahun kedua dan seterusnya dibayar pelanggan (draf), walaupun website masih aktif hingga ${date(state.end)}. Notifikasi dan pembayaran domain terpisah dari langganan.</p><div class="actions"><button data-request="domain_renewal_due">Minta rincian renewal domain</button><button data-request="domain_transfer_requested">Ajukan transfer pengelola</button></div><p id="domain-result" aria-live="polite"></p><p class="simulation">Transfer perlu verifikasi registran, otorisasi, aturan TLD dan biaya registrar. Prototipe tidak meminta auth code atau mengirim transfer.</p>${policyLinks}<h2>Riwayat domain</h2>${list('domain')}</section>${reset}`;
    if(view==='support')account.innerHTML=`<div class="flow-grid"><section class="flow-card"><h2>Ajukan revisi website</h2><p>Revisi minor tanpa batas jumlah selama langganan aktif. CMS dapat dipakai untuk field konten yang didukung.</p><form id="revision-form" novalidate><label for="revision-type">Jenis permintaan</label><select id="revision-type"><option value="minor">Minor — teks, kontak, tautan, foto pada slot</option><option value="major">Besar — layout, halaman, fitur, integrasi</option><option value="incident">Gangguan website</option></select><label for="revision-page">Halaman / bagian website</label><input id="revision-page" maxlength="2000"><label for="revision-before">Kondisi sekarang</label><textarea id="revision-before" maxlength="2000"></textarea><label for="revision-after">Perubahan yang diminta</label><textarea id="revision-after" maxlength="2000"></textarea><label for="revision-material">Keterangan materi pendukung (opsional)</label><textarea id="revision-material" maxlength="2000"></textarea><p id="revision-error" class="error"></p><button class="primary">Ajukan revisi simulasi</button><p id="revision-result" aria-live="polite"></p></form></section><section class="flow-card"><h2>Cakupan dan status</h2><p>Minor tidak mengubah struktur, komponen atau fungsi. Foto harus disediakan pelanggan. Pekerjaan besar perlu estimasi dan persetujuan terpisah; tidak ditagih otomatis.</p><p>Permintaan ditinjau, menunggu materi bila perlu, lalu masuk antrean. Tidak ada batas jumlah tersembunyi atau janji SLA yang belum disahkan.</p><a href="terms.html">Baca definisi revisi</a><h2>Riwayat revisi</h2>${list('revision')}</section></div>${reset}`;
    if(view==='data')account.innerHTML=`<section class="flow-card"><h2>Aset bisnis tetap milik Anda</h2><p>Draf membedakan aset pelanggan, lisensi template selama aktif, karya khusus, aset pihak ketiga, output AI, dan IP RasioLabs Custom. Source code, plugin berbayar, secret dan credential internal tidak termasuk ekspor.</p><div class="actions"><button id="export-content" class="primary">Ekspor konten contoh (JSON)</button><button data-request="data_export_requested">Minta ekspor aset</button><a href="#domain">Transfer pengelola domain</a></div><p id="data-result" aria-live="polite"></p><form id="delete-form" novalidate><h2>Permintaan hapus data</h2><label class="consent"><input id="delete-consent" type="checkbox"><span>Saya memahami ini permintaan peninjauan simulasi, bukan penghapusan langsung atau penghentian website.</span></label><p id="delete-error" class="error"></p><button>Ajukan peninjauan penghapusan</button><p id="delete-result" aria-live="polite"></p></form><details><summary>Usulan transisi dan retensi</summary><p>Jendela ekspor 30 hari setelah kontrak dan retensi pemulihan 60 hari masih memerlukan approval bisnis/hukum, termasuk titik awal periode, backup dan kewajiban penyimpanan. Tidak ada penghapusan otomatis.</p></details>${policyLinks}<h2>Riwayat permintaan data</h2>${list('data')}</section>${reset}`;
    if(view==='onboarding')account.innerHTML=`<section class="flow-card"><h2>Materi untuk menyiapkan website</h2><p>Gunakan template existing. Tidak ada halaman, sektor atau template baru dalam alur ini.</p><form id="materials-form" novalidate><label for="materials-template">Template</label><select id="materials-template">${templates.map((t,i)=>`<option value="${t}">${labels[i]}</option>`).join('')}</select><label for="materials-notes">Materi dan konten yang akan disiapkan</label><textarea id="materials-notes" maxlength="2000" placeholder="Logo, teks layanan, kontak, dan foto untuk slot template."></textarea><label class="consent"><input id="materials-consent" type="checkbox"><span>Saya memiliki hak penggunaan materi dan memahami CMS/revisi minor hanya mencakup konten yang didukung template.</span></label><p id="materials-error" class="error"></p><button class="primary">Simpan materi simulasi</button><p id="materials-result" aria-live="polite"></p></form><p>Halaman, fitur, integrasi atau perubahan layout baru akan melalui estimasi terpisah. Jadwal/SLA perlu ditetapkan bisnis; tidak ada janji otomatis 1–2 hari.</p>${policyLinks}</section>${reset}`;
    account.querySelector('#reset-simulation').onclick=()=>{state=initial();persist();render();};
    account.querySelectorAll('form').forEach(bindValidation);
    const stop=account.querySelector('#stop-form');if(stop)stop.onsubmit=e=>{e.preventDefault();const c=stop.querySelector('input');if(!c.checked)return errorFor(stop,'Konfirmasikan akhir masa aktif.',c);state.stopAtEnd=true;request('subscription','Tidak memperpanjang; website tetap aktif hingga '+date(state.end),{state:'stop_at_end_of_term'});render();feedback(account.querySelector('#stop-result'),'Simulasi tersimpan. Website tidak dinonaktifkan dan tidak ada refund/penagihan yang dijalankan.');};
    const renew=account.querySelector('#renew-duration');if(renew){const draw=()=>{const m=Number(renew.value),end=new Date(state.end+'T12:00:00Z');end.setUTCMonth(end.getUTCMonth()+m);account.querySelector('#renew-summary').innerHTML=facts([['Mulai periode berikutnya',date(state.end)],['Akhir periode berikutnya',date(end.toISOString().slice(0,10))],['Durasi',m+' bulan'],['Harga ekuivalen / total renewal','Menunggu penawaran yang disetujui'],['Domain/email terpisah','Ditampilkan jika berlaku']])+'<p class="simulation">Harga akuisisi tidak otomatis menjadi tarif renewal. Konfirmasi pembayaran tetap terkunci.</p>';};renew.onchange=draw;draw();account.querySelector('#renew-request').onclick=()=>{const r=request('subscription','Penawaran renewal '+renew.value+' bulan diminta.',{state:'renewal_requested',renewal_opt_in:false});feedback(account.querySelector('#renew-result'),r.id+' — simulasi permintaan dicatat. Belum ada persetujuan bayar; penawaran harus menampilkan ekuivalen bulanan, total, tanggal, dan biaya terpisah.');};}
    const refund=account.querySelector('#refund-form');if(refund)refund.onsubmit=e=>{e.preventDefault();const reason=refund.querySelector('textarea');if(!reason.value.trim())return errorFor(refund,'Jelaskan alasan permohonan.',reason);const r=request('refund',refund.querySelector('select').value+': '+reason.value.trim(),{state:'refund_under_review'});render();feedback(account.querySelector('#refund-result'),r.id+' — permohonan simulasi ditinjau. Nilai dan waktu refund belum ditetapkan; tidak ada dana dikembalikan. Keputusan harus memuat rincian pekerjaan/biaya dan jalur keberatan.');};
    const revision=account.querySelector('#revision-form');if(revision)revision.onsubmit=e=>{e.preventDefault();const input={type:revision.querySelector('select').value};for(const k of ['page','before','after','material'])input[k]=revision.querySelector('#revision-'+k).value;let data;try{data=makeRevision(input);}catch(err){return errorFor(revision,err.message,['page','before','after'].map(k=>revision.querySelector('#revision-'+k)).find(e=>!e.value.trim()));}const r=request('revision',data.page+': '+data.after,data);render();feedback(account.querySelector('#revision-result'),r.id+' — '+(data.revision_type==='major'?'Menunggu estimasi terpisah.':'Permintaan masuk untuk ditinjau.')+' Hanya simulasi; tidak dikirim ke tim.');};
    account.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>{const kind=view==='domain'?'domain':'data',r=request(kind,b.textContent,{state:b.dataset.request});render();feedback(account.querySelector('#'+kind+'-result'),r.id+' — permintaan simulasi dicatat, belum dikirim atau dijalankan.');});
    const del=account.querySelector('#delete-form');if(del)del.onsubmit=e=>{e.preventDefault();if(!del.querySelector('input').checked)return errorFor(del,'Baca dan konfirmasikan cakupan permintaan.',del.querySelector('input'));const r=request('data','Permintaan peninjauan penghapusan data.',{state:'data_deletion_requested'});render();feedback(account.querySelector('#delete-result'),r.id+' — hanya permintaan simulasi. Tidak ada data yang dihapus.');};
    const exporter=account.querySelector('#export-content');if(exporter)exporter.onclick=()=>{const blob=new Blob([JSON.stringify({businessName:'Bisnis Contoh',content:{title:'Website bisnis contoh',services:[]},prototype:true},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='konten-bisnis-contoh.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);request('data','Ekspor JSON konten contoh.',{state:'data_export_requested'});feedback(account.querySelector('#data-result'),'JSON berisi konten contoh saja; tidak memuat source code, kredensial atau data pelanggan nyata.');};
    const materials=account.querySelector('#materials-form');if(materials){if(state.materials){materials.querySelector('select').value=templates.includes(state.materials.template)?state.materials.template:'';materials.querySelector('textarea').value=state.materials.notes;}materials.onsubmit=e=>{e.preventDefault();const notes=materials.querySelector('textarea'),c=materials.querySelector('input');if(!notes.value.trim())return errorFor(materials,'Isi daftar materi yang akan disiapkan.',notes);if(!c.checked)return errorFor(materials,'Konfirmasikan hak penggunaan materi dan cakupan.',c);state.materials={template:materials.querySelector('select').value,notes:notes.value.trim()};const saved=persist();feedback(materials.querySelector('#materials-result'),saved?'Materi simulasi tersimpan di tab ini; belum dikirim ke Rasio.':'Penyimpanan tab tidak tersedia. Materi hanya ada di layar saat ini.');};}
  }
  window.addEventListener('hashchange',()=>{if(location.hash!=='#main')render();});render();
}
